        "instruction": "Heat a dry frying pan over a medium heat. Divide the dough into four to six balls and roll out each into a 1cm-thick circle on a lightly floured surface. Fry, one at a time, for 2 mins on each side until cooked through and lightly charred. Top with the feta yogurt, harissa, roasted onions, a bit of extra thyme and honey, and a pinch of sea salt.",
