    "figureCaption": "Plate 32 — Crispy beef with egg fried rice, photographed from The Cookbook kitchen archive.",
    "storyExcerpt": "This one has taken me a while to perfect. The trick for me has been getting a professional steel wok and cooking the beef in batches in hot oil for long enough. My previous wok was cast iron and impossible to wok toss due the weight of it.",
