      "I have loved spaghetti and meatballs since I can remember and I think the same could be said for my daughter. She loves this recipe. Personally, I love the different variates you can find from the infamous Swedish Ikea meatballs to Turkey's Kofta - everyone has their own take on the meatball. My SO's family has a wonderful Bosnian recipe so I thought it was time I had my own.",
      "During my quest to conquer the greatest meatball recipe I discovered the French Guy Cooking (Alex) on YouTube. His meatball series in incredible and Alex takes the meatball recipe to another level. While Alex's recipe truly does result in the most perfect meatball there are some things that I do differently. In Alex's meatball series he points out 50% of the meatball is meat so it is really important to get blend of meat right.",
